const T=[['dot','•'],['brush','🖌'],['eraser','🧽'],['select','⬚'],['bucket','🪣'],['undo','↶'],['redo','↷'],['text','T'],['copy','⧉'],['forget','🚫'],['hide','👁']];
function hb(b,click,hold,rel){let t,h;b.onpointerdown=()=>{h=0;t=setTimeout(()=>{h=1;hold()},450)};b.onpointerup=b.onpointerleave=b.onpointercancel=e=>{clearTimeout(t);if(h){h=0;rel&&rel()}else if(e.type=='pointerup')click()}}
const NM={dot:'Mover',brush:'Pincel',eraser:'Borracha',select:'Selecionar',bucket:'Balde',undo:'Desfazer',redo:'Refazer',text:'Texto',copy:'Copiar',forget:'Esquecer',hide:'Ocultar'};
T.forEach(([k,ic])=>{const b=document.createElement('button');b.id='t_'+k;b.innerHTML=`<span class=i>${ic}</span><small>${NM[k]}</small>`;$('#tools').append(b);
 if(k=='dot'){let d,m;b.onpointerdown=e=>{b.setPointerCapture(e.pointerId);const r=$('#tools').getBoundingClientRect();d={x:e.clientX-r.left,y:e.clientY-r.top};m=0};b.onpointermove=e=>{if(!d)return;m=1;const s=$('#stage').getBoundingClientRect(),t=$('#tools');t.style.left=e.clientX-s.left-d.x+'px';t.style.top=e.clientY-s.top-d.y+'px'};b.onpointerup=()=>{if(!m)$('#tools').classList.toggle('hz');d=0}}
 else if(k=='copy')hb(b,cp,()=>{S.mode='copy';cp()});else if(k=='forget')b.onclick=()=>{S.mode='copy';S.clip=null;updT();toast('Copiado esquecido · o botão voltou a ser Copiar')};else b.onclick=()=>tool(k)});
$('#eye').onclick=()=>document.body.classList.toggle('h');
