mids.forEach(([k,ic,t])=>{const b=document.createElement('button');b.innerHTML=`<span class=i>${ic}</span><small>${t}</small>`;b.title=t;$('#mid').append(b);
 if(k=='sv')hb(b,saveLib,()=>lib());else if(k=='ly')hb(b,()=>panel('ly'),()=>explode(1),()=>explode(0));else if(k=='im'){b.style.position='relative';b.style.overflow='hidden';const i=document.createElement('input');i.type='file';i.accept='image/*,.svg';i.style.cssText='position:absolute;inset:0;opacity:0;width:100%;height:100%;cursor:pointer';i.onclick=()=>{S.pm='obj'};i.onchange=()=>{imgIn(i);i.value=''};b.append(i)}else b.onclick=()=>panel(k)});
